int a[200005];
int b[200005];
int c[200005][2];
int d[200005][2];
ll pf[400005][2];
int cnt[400005];

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int tt;
	cin >> tt;
	while (tt--) {
		int n;
		cin >> n;
		string t;
		cin >> t;
		for (int i = 1; i <= n; ++i) {
			a[i] = (t[i-1] == '1');
		}
		cin >> t;
		for (int i = 1; i <= n; ++i) {
			b[i] = (t[i-1] == '1');
		}
		const int o = n;
		for (int i = 0; i <= 2*n; ++i) {
			pf[i][0] = 0;
			pf[i][1] = 0;
			cnt[i] = 0;
		}
		for (int i = 1; i <= n; ++i) {
			c[i][0] = c[i-1][0]+(a[i] == 0);
			c[i][1] = c[i-1][1]+(a[i] == 1);
			pf[o+c[i][0]-c[i][1]][0] += c[i][0];
			pf[o+c[i][0]-c[i][1]][1] += c[i][1];
			cnt[o+c[i][0]-c[i][1]] += 1;
		}
		for (int i = 1; i <= 2*n; ++i) {
			pf[i][0] += pf[i-1][0];
			pf[i][1] += pf[i-1][1];
			cnt[i] += cnt[i-1];
		}
		for (int i = 1; i <= n; ++i) {
			d[i][0] = d[i-1][0]+(b[i] == 0);
			d[i][1] = d[i-1][1]+(b[i] == 1);
		}
		ll ans = 0;
		for (int i = 1; i <= n; ++i) {
			int z = d[i][1]-d[i][0];
			// 0 worth it when delta <= z
			ans += d[i][0]*(ll)cnt[o+z]+pf[o+z][0];
			ans += d[i][1]*(ll)(n-cnt[o+z])+pf[2*n][1]-pf[o+z][1];
		}
		cout << ans << '\n';
	}
	return 0;
}

