for i in range(1, 31):
    dp[i] = i + 1
    for j in range(i):
        dp[i] = dp[i] * dp[j] % MOD

def dfs(v, k):
    if k == 0:
        return 1
    ans = v + 1
    v = min(v - 1, 30)
    k -= 1
    for j in range(v + 1):
        if k >= 1 << j:
            ans = ans * dp[j] % MOD
            k -= 1 << j
        else:
            ans = ans * dfs(j, k) % MOD
            break
    return ans

